"""H2 actual served UI: layout, popovers, stable gestures and no audio/storage.
Uses the existing isolated Chrome CDP helper; expects port 9230 and closes Chrome.
"""
import base64,json,pathlib,runpy,time,urllib.request
C=runpy.run_path('development/design-mode/tests/served-manage-smoke.py',run_name='helper')['CDP'];url='http://127.0.0.1:9230';tab=json.load(urllib.request.urlopen(urllib.request.Request(url+'/json/new?about:blank',method='PUT')));c=C(tab['webSocketDebuggerUrl']);browser=C(json.load(urllib.request.urlopen(url+'/json/version'))['webSocketDebuggerUrl']);checks=0;measurements=[];base=pathlib.Path('development/design-mode/flexible/review')
def ev(code):return c.evaluate(code)
def check(value,label):
 global checks
 assert value,label
 checks+=1;print('PASS',label,flush=True)
def selector(id,suffix):return f'.h1-deck[data-deck="{id}"] '+suffix
def rect(css):return ev('document.querySelector('+json.dumps(css)+').getBoundingClientRect().toJSON()')
def click(css):
 ev('document.querySelector('+json.dumps(css)+').scrollIntoView({block:"nearest"})')
 r=rect(css);assert r['width']>0 and r['height']>0,css
 for kind in ['mousePressed','mouseReleased']:c.call('Input.dispatchMouseEvent',dict(type=kind,x=r['x']+r['width']/2,y=r['y']+r['height']/2,button='left',clickCount=1))
 time.sleep(.04)
def page(id,name):click(selector(id,'.h1-page-nav [data-page='+name+']'))
def snap():return ev('TuneToxDesign.h1.getSnapshot()')
def range_value(css,value):ev('(()=>{const x=document.querySelector('+json.dumps(css)+');x.value='+str(value)+';x.dispatchEvent(new Event("input",{bubbles:true}));})()')
def drag(css,dy):
 r=rect(css);x=r['x']+r['width']/2;y=r['y']+r['height']/2
 for kind,offset in [('pointerdown',0),('pointermove',dy),('pointerup',dy)]:ev('document.querySelector('+json.dumps(css)+').dispatchEvent(new PointerEvent('+json.dumps(kind)+',{bubbles:true,cancelable:true,button:0,pointerId:77,clientX:'+str(x)+',clientY:'+str(y+offset)+'}))')
def capture(name):base.joinpath(name).write_bytes(base64.b64decode(c.call('Page.captureScreenshot',{'format':'png'})['data']))
def fixed_rows():return [rect(selector(1,x)) for x in ['.h1-transport','.h1-page-nav']]
try:
 c.call('Page.enable');c.call('Page.addScriptToEvaluateOnNewDocument',{'source':"window.audioCreates=0;window.storageOpens=0;for(const key of ['AudioContext','webkitAudioContext'])window[key]=class{constructor(){audioCreates++;throw Error('No audio in H2')}};indexedDB.open=()=>{storageOpens++;throw Error('No storage in H2')};"})
 c.call('Emulation.setDeviceMetricsOverride',dict(width=1194,height=834,deviceScaleFactor=1,mobile=True));c.call('Page.navigate',{'url':'http://192.168.50.24:8765/development/design-mode/flexible/?build=h2'});time.sleep(.7)
 check(ev('!!TuneToxDesign.h1&&!window.h1BootError'),'H2 booted without errors')
 check(ev('document.title.includes("H2") && document.querySelector("h1").textContent.includes("DESIGN MODE")'),'Clear H2 Design Mode identity')
 check(ev('document.querySelectorAll(".h2-overview").length===4 && document.querySelectorAll(".h1-stems").length===4'),'Exactly one overview and stem group per deck')
 before=fixed_rows();deckBounds=rect(selector(1,''));overview=rect(selector(1,'.h2-overview'))
 click(selector(1,'.h1-deck-id'));check(snap()['decks'][0]['compact']['menuOpen'],'Deck label opens matching popover')
 check(fixed_rows()==before and rect(selector(1,''))==deckBounds,'Popover never shifts deck or transport geometry')
 check(rect(selector(1,'.h2-menu button'))['height']>=40,'Touch-friendly popover toggles')
 click(selector(1,'[data-control=beatMatch]'));click(selector(1,'[data-control=handoff]'))
 check(snap()['decks'][0]['beatMatch'] and snap()['decks'][0]['handoff'] and not snap()['decks'][0]['tuneMatch'],'Popover toggles are independent')
 check(ev('document.querySelector('+json.dumps(selector(1,'[data-feature=handoff]'))+').dataset.enabled==="true"'),'Subtle status indicators track enabled features')
 check(snap()['decks'][0]['compact']['menuOpen'],'Toggle leaves its menu open')
 click(selector(2,'.h1-deck-id'));check(not snap()['decks'][0]['compact']['menuOpen'] and snap()['decks'][1]['compact']['menuOpen'],'Other deck opener closes outside menu without sharing state')
 ev('document.querySelector('+json.dumps(selector(2,'.h2-menu'))+').dispatchEvent(new KeyboardEvent("keydown",{key:"Escape",bubbles:true,cancelable:true}))')
 check(not snap()['decks'][1]['compact']['menuOpen'],'Escape closes matching menu')
 for kind in ['keyDown','keyUp']:c.call('Input.dispatchKeyEvent',dict(type=kind,key='Enter',code='Enter',windowsVirtualKeyCode=13,nativeVirtualKeyCode=13,**({'text':'\r','unmodifiedText':'\r'} if kind=='keyDown' else {})))
 check(ev('document.querySelector('+json.dumps(selector(2,'.h2-menu'))+').contains(document.activeElement)'),'Keyboard opener focuses popover controls')
 ev('document.activeElement.dispatchEvent(new KeyboardEvent("keydown",{key:"Escape",bubbles:true,cancelable:true}))')
 check(ev('document.activeElement===document.querySelector('+json.dumps(selector(2,'.h1-deck-id'))+')'),'Escape returns focus to deck label')

 click(selector(1,'.h1-deck-id'));click('.h1-brand h1');check(not snap()['decks'][0]['compact']['menuOpen'],'Outside tap closes menu')
 drag('.h1-tuning-cell[data-deck="1"] [data-control=tempo]',-20)
 check(snap()['decks'][0]['tempo']==125 and snap()['decks'][1]['tempo']==120,'H1 header vertical drag remains intact')
 drag('.h1-tuning-cell[data-deck="1"] [data-control=pitch]',-10);check(snap()['decks'][0]['pitch']==.5 and snap()['decks'][0]['tempo']==125,'Pitch remains separate from tempo')
 check(overview['y']<rect(selector(1,'.h1-zoom'))['y'],'Overview sits above horizontal scrolling waveform')
 page(1,'performance');check(snap()['decks'][0]['compact']['waveCue']=='cue','Single combined selector reaches Cue')
 check(rect(selector(1,'.h2-overview'))==overview and fixed_rows()==before,'Overview Play/Main and navigation remain fixed in Cue')
 check(ev('document.querySelector('+json.dumps(selector(1,'.h1-cue'))+').getBoundingClientRect().height>=document.querySelector('+json.dumps(selector(1,'.h1-content'))+').clientHeight-7'),'Cue uses combined performance area')
 check(ev('document.querySelectorAll('+json.dumps(selector(1,'.h1-page-nav [data-page=performance]'))+').length===1'),'No second independent mode toggle')
 click(selector(1,'.loop-on'));check(snap()['decks'][0]['performance']['loopEnabled'],'Existing Cue looping prototype preserved')
 page(1,'performance');check(snap()['decks'][0]['compact']['waveCue']=='waveform','Same selector returns Waveform+Stems')
 check(ev('document.querySelector('+json.dumps(selector(1,'.h1-wave .h1-stems'))+')!==null'),'Waveform and four stems share combined mode')
 page(1,'controls');check(ev('getComputedStyle(document.querySelector('+json.dumps(selector(1,'.h2-overview'))+')).visibility==="hidden"'),'Controls overview off by default')
 check(rect(selector(1,'.performance-controls'))['y']<rect(selector(1,'.h1-stems'))['y'],'Controls keeps EQ/FX above bottom stems')
 range_value('#h1-stem-1-2',.37);drag(selector(1,'[data-control=high] .knob-dial'),-20)
 check(snap()['decks'][0]['stems'][2]==.37 and snap()['decks'][0]['performance']['eq']['high']>0,'Reused stem and knob interactions work')
 click('#h1-tools-open');click('#h2-controls-overview');click('#h1-tools-close')
 check(rect(selector(1,'.h2-overview'))==overview and fixed_rows()==before,'Optional Controls overview uses same position without moving transport')
 beforeState=snap();click('#h1-tools-open');range_value('[data-parameter=overviewHeight]',60)
 check(rect(selector(1,'.h2-overview'))['height']==60,'Overview height control updates immediately')
 range_value('[data-parameter=stemSection]',240);check(rect(selector(1,'.h1-stems'))['height']==240,'Stem section height adjusts immediately')
 range_value('[data-parameter=cuePad]',64);range_value('[data-parameter=sectionGap]',10)
 click('#h1-layout-reset');click('#h1-tools-close');check(snap()==beforeState,'Layout reset preserves all simulated deck/library/menu state')
 page(1,'performance');click('#h1-tools-open');range_value('[data-parameter=waveHeight]',180);click('#h1-tools-close')
 check(rect(selector(1,'.h1-zoom'))['height']==180,'Manual main waveform height immediately changes rendered frame')
 click('#h1-tools-open');click('#h1-layout-reset');click('#h1-tools-close')
 check(rect(selector(1,'.h1-zoom'))['height']>180,'Reset restores automatic space-filling waveform')
 page(1,'library');click(selector(1,'.column-playlists-tab'));click(selector(1,'[data-playlist-id=afterhours]'))
 ev('(()=>{const x=document.querySelector('+json.dumps(selector(1,'.column-search'))+');x.value="Night";x.dispatchEvent(new Event("input"));})()')
 page(1,'controls');page(1,'library');check(snap()['columnLibraries'][0]['songQuery']=='Night' and snap()['columnLibraries'][1]['songQuery']=='','Independent existing library state survives pages')
 click(selector(1,'.song-manage'));check(snap()['columnLibraries'][0]['context']['songId']=='night','Existing Manage navigation reused')
 click(selector(1,'.context-back'))
 page(2,'controls');page(3,'performance');click(selector(4,'.h1-deck-id'));capture('h2-mixed-ipad.png')
 c.call('Page.reload');time.sleep(.6)
 for w,h in [(1194,834),(1024,768),(390,844),(320,568)]:
  c.call('Emulation.setDeviceMetricsOverride',dict(width=w,height=h,deviceScaleFactor=1,mobile=True));time.sleep(.2)
  decks=[rect(selector(id,'')) for id in [1,2,3,4]]
  check(all(r['width']>0 and r['height']>0 for r in decks),'Four visible decks '+str((w,h)))
  check(ev('document.documentElement.scrollWidth<=innerWidth&&document.documentElement.scrollHeight<=innerHeight'),'Fixed viewport '+str((w,h)))
  check((decks[2]['y']>decks[0]['y'])==(w<600),'Tablet columns / phone 2x2 order')
  rows=fixed_rows();ov=rect(selector(1,'.h2-overview'));page(1,'performance')
  check(rect(selector(1,'.h2-overview'))==ov and fixed_rows()==rows,'Mode switch preserves fixed overview and transport '+str(w))
  page(1,'performance')
  check(ev('document.querySelector('+json.dumps(selector(1,'.h1-wave .h1-stems'))+')!==null'),'Wave+Stems paired on every device')
  ev('window.stemRemovals=0;window.testStem=document.querySelector('+json.dumps(selector(1,'.h1-stems'))+');window.watchStem=new MutationObserver(rows=>{for(const r of rows)if([...r.removedNodes].includes(testStem))stemRemovals++;});watchStem.observe(document.querySelector('+json.dumps(selector(1,'.h1-content'))+'),{subtree:true,childList:true});for(let i=0;i<5;i++)TuneToxDesign.h1.render();')
  check(ev('stemRemovals===0'),'No repeated stem DOM reparenting during render '+str(w))
  ev('watchStem.disconnect()')
  measurements.append(dict(width=w,height=h,deckHeight=decks[0]['height'],contentHeight=rect(selector(1,'.h1-content'))['height'],overviewHeight=ov['height'],waveformHeight=rect(selector(1,'.h1-zoom'))['height'],stemHeight=rect(selector(1,'.h1-stems'))['height']))
  if w==1194:capture('h2-ipad.png')
  if w==390:capture('h2-phone.png')
 check(ev('audioCreates===0&&storageOpens===0&&typeof appState==="undefined"'),'No audio or storage initialization')
 check(ev('performance.getEntriesByType("resource").every(e=>!e.name.includes("/media/")&&!e.name.includes("/playable/")&&!e.name.includes("handoff-deps"))'),'No production/media requests')
 check(ev('!window.h1BootError'),'No script errors')
 base.joinpath('measurements.json').write_text(json.dumps(measurements,indent=2)+'\n')
 print('TOTAL',checks,flush=True)
finally:
 try:browser.call('Browser.close')
 except:pass
